/** Standard tax codes indexed by `code`. */
export const TAX_CODES_BY_CODE: ReadonlyMap<string, TaxCode> = new Map(
  TAX_CODES.map((entry) => [entry.code, entry]),
);

/** Look up a standard tax code by its exact code string. */
export function taxCode(code: string): TaxCode | undefined {
  return TAX_CODES_BY_CODE.get(code);
}
